await page.goto('https://demo.guru99.com/test/newtours/register.php');
await page.locator('input[name="firstName"]').fill('Alex');
await page.locator('input[name="lastName"]').fill('Example');
await page.locator('input[name="userName"]').fill('alexexample');
await page.locator('input[name="password"]').fill('Demo1234');
await page.locator('input[name="confirmPassword"]').fill('Demo1234');
await page.locator('input[name="submit"]').click();
await page.evaluate(() => { const text = document.body.innerText; const match = text.match(/Thank you for registering[^\n.]*(?:\.)?/i); const answer = match?.[0] || ''; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: answer || text.slice(0,500), values: ['Alex', 'Example', 'alexexample'], answer}); });
